classes.ZeroArgSchemaProbe62:
public class ZeroArgSchemaProbe62 {
    private static Map<String, Object> construct(Schema.SObjectType token) {
        Account seed = new Account(Name = 'sentinel');
        SObject caller = seed;
        Map<String, Object> row = new Map<String, Object>();
        String stage = 'before-call';
        try {
            stage = 'calling-newSObject';
            caller = token.newSObject();
            stage = 'assigned';
            row.put('success', true);
            row.put('resultType', caller.getSObjectType().getDescribe().getName());
            row.put('idNull', caller.Id == null);
        } catch (Exception error) {
            row.put('success', false);
            row.put('exceptionType', error.getTypeName());
            row.put('exceptionMessage', error.getMessage());
        }
        row.put('stage', stage);
        row.put('callerAfterType', caller.getSObjectType().getDescribe().getName());
        row.put('preservedSeedName', seed.Name);
        return row;
    }

    public static String observe() {
        return JSON.serialize(new Map<String, Object>{
            'profile' => construct(Profile.SObjectType),
            'account' => construct(Account.SObjectType)
        });
    }
}

